import{_ as e,a as d,o,a4 as a}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Cart & Checkout mapping","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-graphql-mapping/shop/cart-checkout.md","filePath":"api/rest-graphql-mapping/shop/cart-checkout.md","lastUpdated":1784902076000}'),c={name:"api/rest-graphql-mapping/shop/cart-checkout.md"};function r(s,t,p,i,h,n){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="cart-checkout-mapping" tabindex="-1">Cart &amp; Checkout mapping <a class="header-anchor" href="#cart-checkout-mapping" aria-label="Permalink to &quot;Cart &amp; Checkout mapping&quot;">​</a></h1><p>The cart and checkout flow is a sequence — the same on both transports. The difference is naming: REST uses one path per step; GraphQL wraps each step as a mutation (most prefixed <code>create…</code>) and reads as a query.</p><p>Auth for this flow: a <strong>guest</strong> cart uses the cart token as the Bearer; a <strong>logged-in</strong> customer uses their customer token. See <a href="/api/rest-graphql-mapping/shop/auth-context.html">Auth &amp; Context</a>.</p><h2 id="cart" tabindex="-1">Cart <a class="header-anchor" href="#cart" aria-label="Permalink to &quot;Cart&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>Create guest cart token</td><td><code>POST /api/shop/cart-tokens</code></td><td><code>createCartToken</code></td></tr><tr><td>Read cart</td><td><code>POST /api/shop/cart</code></td><td><code>createReadCart</code></td></tr><tr><td>Add item</td><td><code>POST /api/shop/cart/add-to-cart</code></td><td><code>createAddProductInCart</code></td></tr><tr><td>Update item quantity</td><td><code>PUT /api/shop/cart/update-cart-item</code></td><td><code>createUpdateCartItem</code></td></tr><tr><td>Remove item</td><td><code>POST /api/shop/cart/remove-cart-item</code></td><td><code>createRemoveCartItem</code></td></tr><tr><td>Apply coupon</td><td><code>POST /api/shop/cart/apply-coupon</code></td><td><code>createApplyCoupon</code></td></tr><tr><td>Remove coupon</td><td><code>POST /api/shop/cart/remove-coupon</code></td><td><code>createRemoveCoupon</code></td></tr><tr><td>Merge guest cart on login</td><td><code>POST /api/shop/cart/merge-cart</code></td><td><code>createMergeCart</code></td></tr><tr><td>Upload customizable-option file</td><td><code>POST /api/shop/cart/upload-customizable-file</code></td><td>— REST only (binary upload)</td></tr></tbody></table><h2 id="checkout" tabindex="-1">Checkout <a class="header-anchor" href="#checkout" aria-label="Permalink to &quot;Checkout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>Read saved addresses</td><td><code>GET /api/shop/checkout/get-addresses</code></td><td><code>collectionGetCheckoutAddresses</code></td></tr><tr><td>Set billing / shipping address</td><td><code>POST /api/shop/checkout/set-billing-address</code> (or <code>set-shipping-address</code>)</td><td><code>createCheckoutAddress</code></td></tr><tr><td>Get shipping methods (rates)</td><td><code>GET /api/shop/checkout/get-shipping-methods</code></td><td><code>collectionShippingRates</code></td></tr><tr><td>Set shipping method</td><td><code>POST /api/shop/checkout/set-shipping-method</code></td><td><code>createCheckoutShippingMethod</code></td></tr><tr><td>Get payment methods</td><td><code>GET /api/shop/checkout/get-payment-methods</code></td><td><code>collectionPaymentMethods</code></td></tr><tr><td>Set payment method</td><td><code>POST /api/shop/checkout/set-payment-method</code></td><td><code>createCheckoutPaymentMethod</code></td></tr><tr><td>Place order</td><td><code>POST /api/shop/checkout/place-order</code></td><td><code>createCheckoutOrder</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Two things every checkout client must know</p><ul><li><strong>Shipping rates are empty until an address is saved.</strong> Call set-address first; only then do get-shipping-methods / get-payment-methods return options.</li><li><strong><code>createCheckoutAddress</code> input is flat</strong>, not nested — <code>billingFirstName</code>, <code>billingAddress</code>, <code>billingCountry</code>, <code>billingPostcode</code>, <code>useForShipping</code>, and the <code>shipping*</code> equivalents. A nested <code>{ billing {}, shipping {} }</code> is rejected.</li></ul></div><h2 id="offsite-payment-redirect" tabindex="-1">Offsite payment redirect <a class="header-anchor" href="#offsite-payment-redirect" aria-label="Permalink to &quot;Offsite payment redirect&quot;">​</a></h2><p>For gateway methods (Stripe, PayU, PhonePe, Razorpay, PayPal), <strong>set payment method</strong> returns a non-null <code>paymentGatewayUrl</code> — redirect the shopper there, and the order is created when they return to the success URL. On-site methods (<code>cashondelivery</code>, <code>moneytransfer</code>) return <code>null</code> and go straight to place-order. See the <a href="/api/workflows/shop/checkout.html">Checkout workflow</a>.</p>',10)]))}const m=e(c,[["render",r]]);export{u as __pageData,m as default};
